package com.nyayaconnect.casemgmt;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.audit.AuditService;import com.nyayaconnect.common.*;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import jakarta.servlet.http.*;import org.springframework.jdbc.core.JdbcTemplate;import java.io.IOException;import java.util.*;
public final class CaseActionServlet extends HttpServlet {
 private JdbcTemplate db; private CaseAccessService access; private AuditService audit;
 public void init(){db=SpringAccess.bean(getServletContext(),JdbcTemplate.class);access=SpringAccess.bean(getServletContext(),CaseAccessService.class);audit=SpringAccess.bean(getServletContext(),AuditService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);String[] p=req.getPathInfo().split("/");if(p.length<3)throw new IllegalArgumentException("Case action is required.");UUID caseId=UUID.fromString(p[1]);access.requireAccess(u,caseId);String action=p[2];if("tasks".equals(action)){if(p.length<4)throw new IllegalArgumentException("Task id is required.");UUID task=UUID.fromString(p[3]);int n=db.update("update case_tasks set status=CASE WHEN status='COMPLETED' then 'TODO' else 'COMPLETED' end where id=? and case_id=?",task.toString(),caseId.toString());if(n!=1)throw new SecurityException("Task not found in this case.");audit.record(u,"CASE_TASK_TOGGLE","case_task",task.toString(),"SUCCESS",req.getRemoteAddr(),String.valueOf(req.getAttribute("X-Correlation-Id")));Api.json(res,200,Map.of("status","UPDATED","taskId",task));return;}if("timeline".equals(action)){Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);String title=value(b,"title","Case update");String desc=value(b,"description","");String type=value(b,"eventType","DOCUMENT");UUID id=UUID.randomUUID();db.update("insert into case_timeline(id,case_id,event_type,title,description,created_by) values(?,?,?,?,?,?)",id.toString(),caseId.toString(),type,title,desc,u.id().toString());audit.record(u,"CASE_TIMELINE_ADD","case",caseId.toString(),"SUCCESS",req.getRemoteAddr(),String.valueOf(req.getAttribute("X-Correlation-Id")));Api.json(res,201,Map.of("id",id,"status","CREATED"));return;}throw new IllegalArgumentException("Unknown case action.");}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException e){Api.error(res,400,"INVALID_REQUEST",e.getMessage());}catch(Exception e){Api.error(res,500,"CASE_ACTION_FAILED","Case action could not be completed.");}}
 private static String value(Map<?,?>m,String k,String d){Object v=m.get(k);return v==null?d:String.valueOf(v);}
}
